const leftGroups=partGroups;let leftSteps=steps,leftOperations=operations;
if(DATA.modules){const leftModule=DATA.modules.find(m=>m.id==='left-leg');if(leftModule){leftOperations=[leftModule.operations.map(o=>({...o,screws:c=>(o.screwIds||[]).includes(c.id)}))];leftSteps=[{title:'Left leg',shortTitle:'Left leg',keys:leftModule.partKeys,check:leftModule.checks.join(' ')}];steps=leftSteps;operations=leftOperations;}}
if(DATA.leftScrewIds){const allowed=new Set(DATA.leftScrewIds);for(const o of leftOperations.flat()){if(o.screws){const original=o.screws;o.screws=c=>allowed.has(c.id)&&original(c);}}}
let buildSection='left-leg',sectionKeys=new Set(leftGroups.flatMap(g=>g.keys));
function sectionParts(){return DATA.parts.filter(p=>sectionKeys.has(p.key));}
function sectionScrews(){if(buildSection==='left-leg')return DATA.screws.filter(c=>leftOperations.flat().some(o=>o.screws?.(c)));const mod=DATA.modules?.find(m=>m.id===buildSection);const ids=new Set(mod?.operations.flatMap(o=>o.screwIds||[])||[]);return DATA.screws.filter(c=>ids.has(c.id));}
function selectBuildSection(id){
 resetInteraction();buildSection=id;
 if(id==='left-leg'){partGroups=leftGroups;steps=leftSteps;operations=leftOperations;sectionKeys=new Set(leftGroups.flatMap(g=>g.keys));}
 else {const mod=DATA.modules.find(m=>m.id===id);sectionKeys=new Set(mod.partKeys);partGroups=mod.partKeys.map(k=>({keys:[k],name:DATA.parts.find(p=>p.key===k).name,quantity:1}));steps=[{title:mod.title,shortTitle:mod.title,keys:mod.partKeys,check:(mod.checks||[]).join(' ')}];operations=[mod.operations.map(o=>({...o,screws:c=>(o.screwIds||[]).includes(c.id)}))];}
 stage=1;operation=0;document.querySelector('h1').textContent=(id==='left-leg'?'Left leg':DATA.modules.find(m=>m.id===id).title)+' · identify, prepare, assemble';document.querySelector('.tag').textContent=sectionParts().filter(p=>p.key.startsWith('motor')).length+' motors · existing printed parts · unpowered assembly';setSection('parts');host.dataset.buildSection=id;
}
function initBuildSections(){if(!DATA.modules)return;const sel=$('build-section');sel.hidden=false;sel.innerHTML='<option value="left-leg">Left leg</option>'+DATA.modules.filter(m=>m.id!=='left-leg').map(m=>`<option value="${m.id}">${m.title}</option>`).join('');sel.onchange=e=>selectBuildSection(e.target.value);}
function currentOperation(){return operations[stage-1][operation];}
function movingPartKeys(){return [...new Set([...(currentOperation().add||[]),...(currentOperation().moveKeys||[])])];}
function activeScrews(){return section==='assembly'?(currentOperation().screws?DATA.screws.filter(currentOperation().screws):[]):DATA.screws;}
function assembledKeys(){const mod=DATA.modules?.find(m=>m.id===buildSection),context=mod?.partKeys.filter(k=>!(mod.ownedPartKeys||[]).includes(k))||[];return new Set([...context,...operations.flatMap((ops,i)=>i<stage-1?ops.filter(o=>o.add).flatMap(o=>o.add):i===stage-1?ops.slice(0,operation+1).filter(o=>o.add).flatMap(o=>o.add):[])]);}
function goOperation(delta){resetInteraction();mode='assembly';operation+=delta;if(operation>=operations[stage-1].length){if(stage<operations.length){stage++;operation=0;}else operation=operations[operations.length-1].length-1;}if(operation<0){if(stage>1){stage--;operation=operations[stage-1].length-1;}else operation=0;}selectedScrew=null;showScrews=currentOperation().kind==='fasten';$('screws-toggle').classList.toggle('active',showScrews);$('screws-toggle').setAttribute('aria-pressed',showScrews);assemblyPanel();applyView();panel.scrollTop=0;}

function sourceFooter(){return `<div class="sources"><details><summary>Sources and build notes</summary><p>Colors: saved <a href="sources/print-colors.json">89-instance print manifest</a>. Orange/black retained plates use their recorded print groups; old filament presets still show green. Colors have not been checked in individual new photos.</p><p>Shapes: FanGe repo's actual community 3MF meshes, rigidly placed against the current robot model. Foot 44 and ankle 66 are aligned by their native retaining holes and mating faces; exact physical fit requires a dry-fit.</p><p>Fasteners: <a href="sources/motor-fasteners.json">current per-hole geometry audit</a> plus the recovered ankle-to-foot M2×6 TAP. That extra screw is a geometric inference: 2 mm head-seat stack, 4 mm pilot engagement, 1 mm of pilot remaining before the boss exit. Manufacturer <a href="https://emanual.robotis.com/docs/en/dxl/x/xl330-m288/">XL330 documentation</a>. CAD checks are distinct from physical assembly.</p><p>P5 / P6 · Checked 7 October 2026. No hardware has been powered or physically inspected by this page.</p></details></div>`;}
function partPanel(){thumbnails();panel.innerHTML=`<div class="eyebrow">01 · Identify each item</div><h2>Put these parts on the desk</h2><p class="intro">Match shape first, then color. Click a card to inspect that exact part in 3D. Drag to rotate; scroll to zoom.</p><div id="part-detail"></div><div class="cards">${partGroups.map((g,i)=>{const p=DATA.parts.find(p=>p.key===g.keys[0]);return `<button class="partcard" data-part="${i}" aria-label="Inspect ${g.name}"><img alt="Actual shape of ${g.name}" src="${thumbs[g.keys[0]]}"><div class="body"><span class="name">${g.name}</span><div class="meta"><span class="count">×${g.quantity}</span><span class="swatch" style="background:${p.color}"></span>${p.colorName==='Motor'?'Black case':p.colorName}</div></div></button>`;}).join('')}</div><div class="note">${buildSection.includes('leg')?'These leg stations use integrated printed rear retainers and the sliding rings shown above.':'Match the source ID and shape of each printed part. The neck has separate idler pieces; other modules use the retainers listed in their own steps.'}</div><button class="more" id="to-screws">Next · prepare the screws</button>${sourceFooter()}`;
 panel.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>choosePart(+b.dataset.part));$('to-screws').onclick=()=>setSection('screws');}
function choosePart(i){selected=partGroups[i];mode='single';const p=DATA.parts.find(p=>p.key===selected.keys[0]);$('part-detail').innerHTML=`<div class="detail"><h3>${selected.name} · ${selected.quantity} required</h3><p>${p.description}</p><p><strong>${p.colorName==='Motor'?'Black case':p.colorName}</strong> · ${p.dimensions.join(' × ')} mm bounding size</p><p>${p.aliases}</p><button id="all-parts">Back to all individual parts</button></div>`;$('all-parts').onclick=()=>{selected=null;mode='kit';$('part-detail').innerHTML='';applyView();};applyView();panel.scrollTop=0;}
function screwSvg(d,l){const len=l*7;return `<svg viewBox="0 0 105 42" aria-hidden="true"><rect x="9" y="15" width="10" height="14" rx="4" fill="#343c39"/><rect x="19" y="20" width="${len}" height="4" fill="#525b56"/>${Array.from({length:l*2},(_,i)=>`<path d="M${20+i*3.5} 18 l2 8" stroke="#7e8780" stroke-width="1.5"/>`).join('')}<path d="M19 35H${19+len}" stroke="#799081"/><text x="${19+len/2}" y="12" font-size="9" text-anchor="middle" fill="#637a6b">${l} mm</text></svg>`;}
function leftScrewPanel(){panel.innerHTML=`<div class="eyebrow">02 · Prepare fasteners</div><h2>${sectionScrews().length} screws + ${sectionParts().filter(p=>p.geometryKind==='specified-fastener-envelope'&&p.key.startsWith('washer')).length} washers</h2><p class="intro">For the detached leg, including the ID10 output. Includes 34 motor-joint screws and one ankle-to-foot screw. The four ID10 torso case screws are deferred.</p>${Object.entries(sectionScrews().reduce((a,c)=>{a[c.spec]=(a[c.spec]||0)+c.quantity;return a;},{})).map(([spec,q])=>{const m=spec.match(/M([\d.]+) x (\d+)/);const l=+m[2];return `<div class="spec">${screwSvg(+m[1],l)}<div><strong>${spec.replace(' x ',' × ')}</strong><small>${+m[1]===2.6?'Match ROBOTIS BHS rounded head':'PHS / pan head; correct TAP thread required'}</small></div><span class="quantity">× ${q}</span></div>`;}).join('')}<div class="spec"><svg viewBox="0 0 105 42"><ellipse cx="42" cy="22" rx="18" ry="10" fill="#9baba0"/><ellipse cx="42" cy="22" rx="9.5" ry="5" fill="#fbfcf8"/></svg><div><strong>Metal M2.5 small washer</strong><small>DIN433 / ISO7092 · ID 2.7 · OD 5 · 0.5 mm thick</small></div><span class="quantity">× 2</span></div><div class="note amber"><strong>Photo vs. required specs.</strong> Your photo shows M2×4, ×6, ×8, ×10 TAP and M2.6×6/×8 TAP. M2×5 TAP and the small washers are not identified in the photo; this is a spec check, not a claim that your remaining stock is insufficient. FHS_M3X05 is M3, not the needed M2×5.</div><div class="note">TAP means self-tapping. PHS_M2X06 without TAP is not automatically equivalent. Match diameter, length under the head, thread and head profile—not screw color.</div><details><summary>Why M2×5 at the knee?</summary><p>FanGe's README lists generic M2/M2.5 self-tapping screws; it does not prescribe M2×5 for this joint. Our current audit measures a 2.8 mm head-seat stack. M2×5 enters 2.2 mm; M2×6 would enter 3.2 mm, exceeding the manufacturer's 3.0 mm maximum.</p></details><div class="note amber"><strong>One additional M2×6 TAP:</strong> the yellow foot has a retaining pilot hole matching the orange ankle. Its fastener was missing from the old motor-only schedule; it is included here from native-mesh depth measurements. Keep this screw hand-tight and check the real fit.</div><button class="more" id="to-assembly">Next · assemble the leg</button>${sourceFooter()}`;$('to-assembly').onclick=()=>setSection('assembly');}
function screwPanel(){if(buildSection==='left-leg'){leftScrewPanel();return;}const ss=sectionScrews(),washers=sectionParts().filter(p=>p.key.startsWith('washer'));panel.innerHTML=`<div class="eyebrow">02 · Prepare fasteners</div><h2>${ss.reduce((n,c)=>n+(c.quantity||1),0)} specified screws</h2><p>Prepare these fasteners before this module. Click the numbered insertion markers during its fastening operations.</p>${Object.entries(ss.reduce((a,c)=>{a[c.spec]=(a[c.spec]||0)+(c.quantity||1);return a;},{})).map(([spec,q])=>{const m=spec.match(/M([\d.]+)\s*[x×]\s*(\d+)/);return `<div class="spec">${m?screwSvg(+m[1],+m[2]):''}<strong>${spec.replace(' x ',' × ')}</strong><span class="quantity">× ${q}</span></div>`;}).join('')}${washers.map(p=>`<div class="note"><strong>${p.name}</strong><p>${p.description}</p><button data-find-washer="${p.key}">Show this washer</button></div>`).join('')}<div class="note">Match thread type, diameter, length under the head and head shape. Screw heads and threads in the viewer are schematic; use the listed physical screw specification. Any fitting-only operation explains its separate retention method.</div><button class="more" id="to-assembly">Next · assemble this module</button>${sourceFooter()}`;$('to-assembly').onclick=()=>setSection('assembly');panel.querySelectorAll('[data-find-washer]').forEach(b=>b.onclick=()=>{const p=DATA.parts.find(p=>p.key===b.dataset.findWasher),c=DATA.screws.find(c=>c.id===p.fastenerId);if(c)viewWasher(c);else highlightPart(p.key);});}
