 if($('closure-wire'))$('closure-wire').onclick=()=>setSection('wiring');bindMotionControls();$('previous').onclick=()=>goOperation(-1);$('next').onclick=()=>goOperation(1);$('fit-module').onclick=()=>fit(meshes.filter(m=>m.visible&&steps[stage-1].keys.includes(m.userData.part.key)));
