 panel.innerHTML=`<div class="eyebrow">04 · Wiring · ${wiringStep+1} / ${WIRING.steps.length}</div><h2>${safe(st.title)}</h2><label for="wire-step">Wiring stage</label><select id="wire-step">${WIRING.steps.map((s,i)=>`<option value="${i}" ${i===wiringStep?'selected':''}>${i+1} · ${safe(s.title)}</option>`).join('')}</select><ol>${st.actions.map(a=>`<li>${safe(a)}</li>`).join('')}</ol><div class="note">${safe(st.check)}</div><div class="wire-mode-switch"><button id="wire-installed">On robot · 3D</button><button id="wire-detail">Connector · 3D</button></div><div id="wire-selected-detail"></div>${st.connections.length?'<h3>Select one connection</h3>':''}<div class="wire-connections">${st.connections.map((c,i)=>`<button data-connection="${i}" class="${i===wiringConnection?'active':''}">${safe(c.purpose)}<small>${safe(c.from)} → ${safe(c.to)}</small></button>`).join('')}</div><div class="row"><button id="wire-prev" ${wiringStep===0?'disabled':''}>Previous wiring stage</button><button id="wire-next" ${wiringStep===WIRING.steps.length-1?'disabled':''}>Next wiring stage</button><button id="wire-header">Pi header pin map</button></div><details class="sources"><summary>Reference and hardware checks</summary><p>${safe(WIRING.current_compute_note)}</p><p>${safe(WIRING.fuse_stage_note)}</p><p>Match physical pin 1 and connector markings before making a lead. These are the current design endpoints; loose cables and live voltages have not been physically verified.</p>${(WIRING.sources||[]).map(v=>`<p><a href="${safe(v.url||v.href||'')}">${safe(v.title||v.name||v.id||v.url)}</a></p>`).join('')}</details>`;
 $('wire-step').onchange=e=>{wireMode='installed';wiringStep=+e.target.value;wiringConnection=0;wiringPanel();};$('wire-prev').onclick=()=>{wiringStep--;wiringConnection=0;wiringPanel();};$('wire-next').onclick=()=>{wiringStep++;wiringConnection=0;wiringPanel();};$('wire-header').onclick=()=>headerMap();$('wire-installed').onclick=()=>{wireMode='installed';drawConnection();};$('wire-detail').onclick=()=>{wireMode='connector';drawConnection();};panel.querySelectorAll('[data-connection]').forEach(b=>b.onclick=()=>{wiringConnection=+b.dataset.connection;wiringPanel();});drawConnection();
